    @staticmethod
    def H2_excitation_vib_a(Te: np.ndarray) -> np.ndarray:
        """
        H2 vibrational excitation (v=0 -> v=1).
        e + H2(v=0) -> e + H2(v=1)
        Reaction 2.2.1a - Energy loss ~0.5 eV
        
        Parameters
        ----------
        Te : np.ndarray
            Electron temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        Te_safe = np.clip(Te, 0.158, 2e4)  # Tmin from hydhel.tex, Tmax from C++
        ln_Te = _safe_log(Te_safe)
        
        # From hydhel.tex REAC221a polynomial fit coefficients
        ln_k = (-2.017212494454e+01 + 9.563952280637e-01 * ln_Te
                - 6.931474225637e-01 * ln_Te**2 + 1.673671529631e-01 * ln_Te**3
                - 3.228762898855e-02 * ln_Te**4 + 5.838603222226e-03 * ln_Te**5
                - 8.580542691302e-04 * ln_Te**6 + 7.456311623168e-05 * ln_Te**7
                - 2.666978300757e-06 * ln_Te**8)
        return np.exp(ln_k)
    
    @staticmethod
    def H2_excitation_vib_b(Te: np.ndarray) -> np.ndarray:
        """
        H2 vibrational excitation (v=0 -> v=2).
        e + H2(v=0) -> e + H2(v=2)
        Reaction 2.2.1b - Energy loss ~1.0 eV
        
        Parameters
        ----------
        Te : np.ndarray
            Electron temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        Te_safe = np.clip(Te, 0.398, 2e4)  # Tmin from hydhel.tex, Tmax from C++
        ln_Te = _safe_log(Te_safe)
        
        # From hydhel.tex REAC221b polynomial fit coefficients
        ln_k = (-2.265507686305e+01 + 2.239943592222e+00 * ln_Te
                - 1.099426577160e+00 * ln_Te**2 + 2.339027647223e-01 * ln_Te**3
                - 2.528511103871e-02 * ln_Te**4 + 6.851302489620e-04 * ln_Te**5
                + 1.253426182224e-04 * ln_Te**6 - 1.253475051672e-05 * ln_Te**7
                + 3.545892878015e-07 * ln_Te**8)
        return np.exp(ln_k)
    
    @staticmethod
    def H2_excitation_elec_B(Te: np.ndarray) -> np.ndarray:
        """
        H2 electronic excitation to B state.
        e + H2(X) -> e + H2(B)
        Reaction 2.2.2 - Energy loss ~12.1 eV
        
        Parameters
        ----------
        Te : np.ndarray
            Electron temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        k = np.zeros_like(Te)
        mask = Te >= 0.4  # Threshold from reactionrates.cpp
        Te_safe = np.clip(Te[mask], 2.0, 2e4)  # Tmin from hydhel.tex, Tmax from C++
        ln_Te = _safe_log(Te_safe)
        
        # From hydhel.tex REAC222 polynomial fit coefficients
        ln_k = (-3.081902926338e+01 + 1.038866780735e+01 * ln_Te
                - 4.259768348687e+00 * ln_Te**2 + 1.181228673120e+00 * ln_Te**3
                - 2.277513907465e-01 * ln_Te**4 + 2.900576728856e-02 * ln_Te**5
                - 2.287591474628e-03 * ln_Te**6 + 1.004346442778e-04 * ln_Te**7
                - 1.869930069131e-06 * ln_Te**8)
        k[mask] = np.exp(ln_k)
        return k
    
