    @staticmethod
    def Hi_H2_charge_exchange(THi: np.ndarray, TH2: np.ndarray) -> np.ndarray:
        """
        Charge exchange: H+ + H2 -> H2+ + H
        Reaction 3.2.3 (REAC323)
        
        Uses center-of-mass temperature interpolation from lookup table.
        
        Parameters
        ----------
        THi : np.ndarray
            H+ temperature [eV].
        TH2 : np.ndarray
            H2 temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        return _HiH2_cx_rate(THi, TH2)
    
    @staticmethod
    def Hi_H2_dissociation(THi: np.ndarray, TH2: np.ndarray) -> np.ndarray:
        """
        Dissociation: H+ + H2 -> H+ + H + H
        Reaction 3.2.8
        
        Parameters
        ----------
        THi : np.ndarray
            H+ temperature [eV].
        TH2 : np.ndarray
            H2 temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        T_avg = (THi + TH2) / 2.0
        T_safe = np.maximum(T_avg, 0.1)
        
        # Threshold at ~4.5 eV
        k = np.zeros_like(T_avg)
        mask = T_safe > 4.5
        k[mask] = 1.0e-9 * np.power((T_safe[mask] - 4.5) / 10.0, 0.5)
        return np.clip(k, 0, 1e-8)
    
    @staticmethod
    def H3i_recombination_H2H(Te: np.ndarray) -> np.ndarray:
        """
        Dissociative recombination of H3+.
        e + H3+ -> H2 + H
        Reaction 2.2.14
        
        Parameters
        ----------
        Te : np.ndarray
            Electron temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        Te_safe = np.maximum(Te, 0.01)
        
        # From reactionrates.cpp REAC2214
        k = 4.4e-8 * np.power(Te_safe / 300.0, -0.5)
        return np.clip(k, 0, 1e-6)
    
