    @staticmethod
    def H2i_H2_to_H3i(TH2i: np.ndarray, TH2: np.ndarray) -> np.ndarray:
        """
        H3+ formation: H2+ + H2 -> H3+ + H
        Reaction 4.2.5
        
        Parameters
        ----------
        TH2i : np.ndarray
            H2+ temperature [eV].
        TH2 : np.ndarray
            H2 temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        # Nearly constant rate ~ 2e-9 cm³/s at low energies
        k = np.full_like(TH2i, 2.0e-9)
        return k
    
    @staticmethod
    def H2_H_dissociation(TH2: np.ndarray, TH: np.ndarray) -> np.ndarray:
        """
        Molecular dissociation by H impact: H2 + H -> H + H + H
        Reaction 4.1.9
        
        Parameters
        ----------
        TH2 : np.ndarray
            H2 temperature [eV].
        TH : np.ndarray
            H temperature [eV].
            
        Returns
        -------
        k : np.ndarray
            Rate coefficient [cm³/s].
        """
        T_avg = (TH2 + TH) / 2.0
        T_safe = np.maximum(T_avg, 0.1)
        
        # Threshold ~4.5 eV
        k = np.zeros_like(T_avg)
        mask = T_safe > 4.5
        k[mask] = 1.0e-10 * np.power((T_safe[mask] - 4.5) / 10.0, 0.8)
        return np.clip(k, 0, 1e-9)
    
