def _elastic_rate_HH2(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """H + H2 elastic collision rate [cm³/s]."""
    m1, m2 = 1.0, 2.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    return np.interp(T, _T_ELASTIC_63, _K_HH2)


def _elastic_rate_HiH(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """H+ + H elastic collision rate [cm³/s]."""
    m1, m2 = 1.0, 1.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    return np.interp(T, _T_ELASTIC_63, _K_HiH)


