def _H2iH2_cx_rate(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """H2+ + H2 -> H2 + H2+ symmetric charge exchange rate [cm³/s] (REAC431)."""
    m1, m2 = 2.0, 2.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    k = np.interp(T, _T_ELASTIC_63, _K_REAC431)
    return _rrion_threshold(k)


def _HeIIHeI_cx_rate(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """He+ + He -> He + He+ symmetric charge exchange rate [cm³/s] (REAC531)."""
    m1, m2 = 4.0, 4.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    k = np.interp(T, _T_ELASTIC_63, _K_REAC531)
    return _rrion_threshold(k)


def _HeIIIHeI_cx_double_rate(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """He++ + He -> He+ + He+ double charge exchange rate [cm³/s] (CXHe3He1).
    Uses 1000-point lookup table from reactionrates.cpp RRCX.
    """
    # C++ clips T1, T2 individually before computing T_eff
    T1 = np.clip(T1, 1.0, 1000.0)
    T2 = np.clip(T2, 1.0, 1000.0)
    # Effective temperature: T_eff = (m1*T2 + m2*T1)/(m1+m2) with m1=4, m2=4
    # T_eff = (4*T2 + 4*T1)/8 = (T1+T2)/2
    T_eff = (T1 + T2) / 2.0
    return np.interp(T_eff, _T_RRCX_1000, _K_CXHe3He1)


def _HeIIIHeI_cx_symmetric_rate(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """He++ + He -> He + He++ symmetric charge exchange rate [cm³/s] (REAC631)."""
    m1, m2 = 4.0, 4.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    k = np.interp(T, _T_ELASTIC_63, _K_REAC631)
    return _rrion_threshold(k)


