def _rrion_threshold(k: np.ndarray) -> np.ndarray:
    """Apply RRion threshold: set values < 1e-20 to 0 (matches C++ reactionrates.cpp)."""
    return np.where(k < 1e-20, 0.0, k)


def _HiH_exc_a_rate(T1: np.ndarray, T2: np.ndarray) -> np.ndarray:
    """H+ + H -> H+ + H* excitation channel a rate [cm³/s] (REAC311)."""
    m1, m2 = 1.0, 1.0
    T = np.clip((T1 * m2 + T2 * m1) / (m1 + m2), 0.01, 20000.0)
    k = np.interp(T, _T_ELASTIC_63, _K_REAC311)
    return _rrion_threshold(k)


